import{_ as t,o as e,c as s,aa as r}from"./chunks/framework.VLjJFeoF.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/js/does-js-and-css-parsing-block-html-parsing.md","filePath":"docs/interview/js/does-js-and-css-parsing-block-html-parsing.md","lastUpdated":1770685239000}'),i={name:"docs/interview/js/does-js-and-css-parsing-block-html-parsing.md"};function o(l,a,d,n,c,h){return e(),s("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1770685239000"},[...a[0]||(a[0]=[r('<h4 id="🧠-一、浏览器加载网页的流程" tabindex="-1">🧠 一、浏览器加载网页的流程<a href="#-一浏览器加载网页的流程"></a> <a class="header-anchor" href="#🧠-一、浏览器加载网页的流程" aria-label="Permalink to &quot;🧠 一、浏览器加载网页的流程[](#-一浏览器加载网页的流程)&quot;">​</a></h4><p>加载一个网页时，浏览器大致会经过这些步骤：</p><ol><li><p><strong>解析 HTML</strong> → 构建 DOM 树</p></li><li><p><strong>解析 CSS</strong> → 构建 CSSOM（CSS Object Model）</p></li><li><p><strong>合并 DOM + CSSOM</strong> → 构建 Render Tree（渲染树）</p></li><li><p><strong>布局（Layout）</strong> → 计算元素位置和大小</p></li><li><p><strong>绘制（Paint）</strong> → 把内容画在屏幕上</p></li></ol><p>现在我们来看 JavaScript 和 CSS 分别在这个流程里是怎么影响的。</p><h4 id="🎨-二、css-的行为" tabindex="-1">🎨 二、CSS 的行为<a href="#-二css-的行为"></a> <a class="header-anchor" href="#🎨-二、css-的行为" aria-label="Permalink to &quot;🎨 二、CSS 的行为[](#-二css-的行为)&quot;">​</a></h4><h5 id="✅-css-会阻塞页面渲染-但不会阻塞-html-解析" tabindex="-1">✅ CSS 会阻塞页面渲染（但不会阻塞 HTML 解析）<a href="#-css-会阻塞页面渲染但不会阻塞-html-解析"></a> <a class="header-anchor" href="#✅-css-会阻塞页面渲染-但不会阻塞-html-解析" aria-label="Permalink to &quot;✅ CSS 会阻塞页面渲染（但不会阻塞 HTML 解析）[](#-css-会阻塞页面渲染但不会阻塞-html-解析)&quot;">​</a></h5><p>当浏览器遇到 <code>&lt;link rel=&quot;stylesheet&quot; href=&quot;style.css&quot;&gt;</code> 这样的标签时，它会异步请求这个 CSS 文件。</p><p><strong>虽然 HTML 解析不会停下来继续进行</strong>，也就是 DOM 树会照常构建，但浏览器不会开始“绘制”页面上的内容（也就是不会显示出来），直到这个 CSS 文件加载并解析完毕。</p><h5 id="为什么-css-阻塞渲染" tabindex="-1">为什么 CSS 阻塞渲染？<a href="#为什么-css-阻塞渲染"></a> <a class="header-anchor" href="#为什么-css-阻塞渲染" aria-label="Permalink to &quot;为什么 CSS 阻塞渲染？[](#为什么-css-阻塞渲染)&quot;">​</a></h5><p>浏览器在渲染页面时需要知道样式信息，如果没有加载完 CSS，浏览器就无法确定页面元素的外观，比如它们的颜色、大小和位置。这样，页面可能会先以没有样式的默认状态显示一会儿，或者显示一些错误的布局，给用户造成“闪烁”或者“布局跳变”的不良体验。因此，浏览器会等 CSS 加载并解析完成后，才会开始最终渲染页面，确保样式和布局的准确性。</p><h4 id="💻-三、javascript-的行为" tabindex="-1">💻 三、JavaScript 的行为<a href="#-三javascript-的行为"></a> <a class="header-anchor" href="#💻-三、javascript-的行为" aria-label="Permalink to &quot;💻 三、JavaScript 的行为[](#-三javascript-的行为)&quot;">​</a></h4><h5 id="❌-js-默认会阻塞-html-解析-尤其是同步加载的" tabindex="-1">❌ JS 默认会阻塞 HTML 解析（尤其是同步加载的）<a href="#-js-默认会阻塞-html-解析尤其是同步加载的"></a> <a class="header-anchor" href="#❌-js-默认会阻塞-html-解析-尤其是同步加载的" aria-label="Permalink to &quot;❌ JS 默认会阻塞 HTML 解析（尤其是同步加载的）[](#-js-默认会阻塞-html-解析尤其是同步加载的)&quot;">​</a></h5><p>当浏览器遇到 <code>&lt;script src=&quot;app.js&quot;&gt;&lt;/script&gt;</code> 这样的脚本：</p><ol><li><strong>HTML 解析暂停</strong>（DOM 构建中止）</li><li>浏览器去下载 JS 文件（同步行为）</li><li>下载完成后，立即执行 JS</li><li>执行完成后，HTML 解析继续</li></ol><h5 id="为什么-js-会阻塞解析" tabindex="-1">为什么 JS 会阻塞解析？<a href="#为什么-js-会阻塞解析"></a> <a class="header-anchor" href="#为什么-js-会阻塞解析" aria-label="Permalink to &quot;为什么 JS 会阻塞解析？[](#为什么-js-会阻塞解析)&quot;">​</a></h5><p><code>JavaScript</code> 可能会动态地修改页面内容，比如通过 <code>document.write()</code> 插入新的 HTML，或者修改 DOM 结构。如果浏览器在解析 HTML 时遇到这些 JavaScript，它无法保证页面结构的完整性和一致性。因此，浏览器必须等 JS 执行完毕后，才能确保 HTML 解析的安全进行，避免出现不完整或混乱的页面结构。</p><h4 id="🚀-四、解决方案-异步加载-js-的两种方式" tabindex="-1">🚀 四、解决方案：异步加载 JS 的两种方式<a href="#-四解决方案异步加载-js-的两种方式"></a> <a class="header-anchor" href="#🚀-四、解决方案-异步加载-js-的两种方式" aria-label="Permalink to &quot;🚀 四、解决方案：异步加载 JS 的两种方式[](#-四解决方案异步加载-js-的两种方式)&quot;">​</a></h4><h5 id="_1-defer" tabindex="-1">1. <code>defer</code><a href="#1-defer"></a> <a class="header-anchor" href="#_1-defer" aria-label="Permalink to &quot;1\\. `defer`[](#1-defer)&quot;">​</a></h5><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;script src=&quot;main.js&quot; defer&gt;&lt;/script&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><p>✅ 异步下载 JS</p></li><li><p>✅ HTML 解析不会被阻塞</p></li><li><p>✅ 在 <strong>DOM 构建完成之后执行</strong></p></li><li><p>✅ 保证多个脚本按顺序执行（重要！）</p></li></ul><p>📌 <strong>推荐使用场景</strong>：几乎所有非内联的 JS 都可以用 <code>defer</code></p><h5 id="_2-async" tabindex="-1">2. <code>async</code><a href="#2-async"></a> <a class="header-anchor" href="#_2-async" aria-label="Permalink to &quot;2\\. `async`[](#2-async)&quot;">​</a></h5><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;script src=&quot;main.js&quot; async&gt;&lt;/script&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>✅ 异步下载 JS</li><li>⚠️ 下载完成就立刻执行（可能早于 HTML 完成）</li><li>❌ 多个 async 脚本之间 <strong>执行顺序不确定</strong></li></ul><p>📌 <strong>适合场景</strong>：统计、广告、第三方库（不依赖 DOM，不互相依赖）</p><h4 id="🧩-五、实际效果小结" tabindex="-1">🧩 五、实际效果小结<a href="#-五实际效果小结"></a> <a class="header-anchor" href="#🧩-五、实际效果小结" aria-label="Permalink to &quot;🧩 五、实际效果小结[](#-五实际效果小结)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>文件类型</th><th>是否阻塞 HTML 解析</th><th>是否阻塞页面渲染</th></tr></thead><tbody><tr><td>CSS</td><td>❌ 不阻塞 HTML 解析</td><td>✅ 阻塞页面渲染</td></tr><tr><td>JS（默认）</td><td>✅ 阻塞 HTML 解析</td><td>✅ 阻塞页面渲染</td></tr><tr><td>JS（defer）</td><td>❌ 不阻塞 HTML 解析</td><td>✅ 等 DOM 完成后执行</td></tr><tr><td>JS（async）</td><td>❌ 不阻塞 HTML 解析</td><td>❌ 立即执行，可能影响渲染时机</td></tr></tbody></table><h4 id="🔧-实际建议" tabindex="-1">🔧 实际建议<a href="#-实际建议"></a> <a class="header-anchor" href="#🔧-实际建议" aria-label="Permalink to &quot;🔧 实际建议[](#-实际建议)&quot;">​</a></h4><ol><li><strong>CSS 永远放在 <code>&lt;head&gt;</code></strong>，确保优先加载，避免渲染阻塞。</li><li><strong>JS 推荐使用 <code>defer</code> 放在 <code>&lt;head&gt;</code></strong>，或放在 <code>&lt;body&gt;</code> 底部。</li><li><strong>不要阻塞主线程</strong>，能异步就异步。</li><li><strong>重要脚本尽量合并和压缩</strong>，减少请求数量和大小。</li></ol><p><a href="https://www.codecrack.cn/zh/javascript/postMessage" title="postMessage 如何区分不同类型的消息" target="_blank" rel="noreferrer">postMessage 如何区分不同类型的消息</a></p>',30)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
